const isPrime = n => {
  if (n < 2)
    return false;
  for (let i = 2; i * i <= n; i++)
    if (n % i === 0)
      return false;
  return true;
};

const fact = n => {
  let r = 1;
  for (let i = 2; i <= n; i++)
    r *= i;
  return r;
};

const fib = n => {
  let [a, b] = [0, 1];
  for (let i = 0; i < n; i++)
    [a, b] = [b, a + b];
  return a;
};

const isArm = n => {
  const d = String(n);
  return [...d].reduce((s, x) => s + x ** d.length, 0) === n;
};

function sieve(n) {
  const p = Array(n + 1).fill(true);
  p[0] = p[1] = false;
  for (let i = 2; i * i <= n; i++)
    if (p[i])
      for (let j = i * i; j <= n; j += i)
        p[j] = false;
  return p.reduce((a, v, i) => v ? [...a, i] : a, []);
}

const bits = n => {
  let c = 0;
  while (n) {
    n &= n - 1;
    c++;
  }
  return c;
};

const isPerfect = n => {
  let s = 0;
  for (let i = 1; i < n; i++)
    if (n % i === 0)
      s += i;
  return s === n && n > 1;
};

function roman(s) {
  const m = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let t = 0;
  for (let i = 0; i < s.length; i++) {
    const v = m[s[i]], n = m[s[i + 1]];
    t += n > v ? -v : v;
  }
  return t;
}

const isPal = s => {
  const c = s.toLowerCase().replace(/[^a-z0-9]/g, '');
  return c === [...c].reverse().join('');
};

const firstUnique = s => {
  const f = freq(s);
  return [...s].find(c => f[c] === 1) ?? null;
};

const maxChar = s => {
  const f = freq(s);
  return Object.keys(f).reduce((a, b) => f[a] >= f[b] ? a : b);
};

function balanced(s) {
  const st = [], p = { ')': '(', ']': '[', '}': '{' };
  for (const c of s) {
    if ('([{'.includes(c))
      st.push(c);
    else if (p[c]) {
      if (st.pop() !== p[c])
        return false;
    }
  }
  return st.length === 0;
}

function compress(s) {
  let r = '', c = 1;
  for (let i = 1; i <= s.length; i++) {
    if (s[i] === s[i - 1])
      c++;
    else {
      r += s[i - 1] + c;
      c = 1;
    }
  }
  return r;
}

const lcp = a => a.reduce((p, s) => {
  while (!s.startsWith(p))
    p = p.slice(0, -1);
  return p;
});

function lps(s) {
  let best = '';
  for (let i = 0; i < s.length; i++)
    for (const [l, r] of [[i, i], [i, i + 1]]) {
      let a = l, b = r;
      while (a >= 0 && b < s.length && s[a] === s[b]) {
        a--;
        b++;
      }
      if (b - a - 1 > best.length)
        best = s.slice(a + 1, b);
    }
  return best;
}

function rev(a) {
  for (let i = 0, j = a.length - 1; i < j; i++, j--)
    [a[i], a[j]] = [a[j], a[i]];
  return a;
}

function twoSum(a, t) {
  const m = new Map();
  for (let i = 0; i < a.length; i++) {
    if (m.has(t - a[i]))
      return [m.get(t - a[i]), i];
    m.set(a[i], i);
  }
  return [];
}

const rotate = (a, k) => {
  k %= a.length;
  return [...a.slice(-k), ...a.slice(0, -k)];
};

const inter = (a, b) => {
  const s = new Set(b);
  return [...new Set(a.filter(x => s.has(x)))];
};

function maxSub(a) {
  let cur = a[0], best = a[0];
  for (let i = 1; i < a.length; i++) {
    cur = Math.max(a[i], cur + a[i]);
    best = Math.max(best, cur);
  }
  return best;
}

function bs(a, t) {
  let l = 0, r = a.length - 1;
  while (l <= r) {
    const m = (l + r) >> 1;
    if (a[m] === t)
      return m;
    a[m] < t ? l = m + 1 : r = m - 1;
  }
  return -1;
}

function bubble(a) {
  for (let i = 0; i < a.length; i++)
    for (let j = 0; j < a.length - i - 1; j++)
      if (a[j] > a[j + 1])
        [a[j], a[j + 1]] = [a[j + 1], a[j]];
  return a;
}

function msort(a) {
  if (a.length < 2)
    return a;
  const m = a.length >> 1, l = msort(a.slice(0, m)), r = msort(a.slice(m)), o = [];
  while (l.length && r.length)
    o.push(l[0] <= r[0] ? l.shift() : r.shift());
  return [...o, ...l, ...r];
}

function merge(a, b) {
  const r = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length)
    r.push(a[i] <= b[j] ? a[i++] : b[j++]);
  return [...r, ...a.slice(i), ...b.slice(j)];
}

function pairs(a, t) {
  const m = new Map();
  let c = 0;
  for (const x of a) {
    c += m.get(t - x) || 0;
    m.set(x, (m.get(x) || 0) + 1);
  }
  return c;
}

function prod(a) {
  const n = a.length, r = Array(n).fill(1);
  let l = 1;
  for (let i = 0; i < n; i++) {
    r[i] = l;
    l *= a[i];
  }
  let rt = 1;
  for (let i = n - 1; i >= 0; i--) {
    r[i] *= rt;
    rt *= a[i];
  }
  return r;
}

function lcs(a) {
  const s = new Set(a);
  let best = 0;
  for (const x of s)
    if (!s.has(x - 1)) {
      let y = x;
      while (s.has(y + 1))
        y++;
      best = Math.max(best, y - x + 1);
    }
  return best;
}

function shuffle(a) {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function profit(p) {
  let min = Infinity, best = 0;
  for (const x of p) {
    min = Math.min(min, x);
    best = Math.max(best, x - min);
  }
  return best;
}

const groupAn = w => Object.values(w.reduce((m, s) => {
  const k = [...s].sort().join('');
  (m[k] ||= []).push(s);
  return m;
}, {}));

function spiral(m) {
