function deepEq(a, b) {
  if (a === b)
    return true;
  if (typeof a !== 'object' || typeof b !== 'object' || !a || !b)
    return false;
  const k = Object.keys(a);
  return k.length === Object.keys(b).length && k.every(x => deepEq(a[x], b[x]));
}

function flatObj(o, p = '', r = {}) {
  for (const k in o) {
    const key = p ? p + '.' + k : k;
    typeof o[k] === 'object' && o[k] ? flatObj(o[k], key, r) : r[key] = o[k];
  }
  return r;
}

const merge = (a, b) => {
  for (const k in b)
    a[k] = (b[k] && typeof b[k] === 'object' && !Array.isArray(b[k])) ? merge(a[k] || {}, b[k]) : b[k];
  return a;
};

function debounce(fn, ms) {
  let t;
  return (...a) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...a), ms);
  };
}

function throttle(fn, ms) {
  let last = 0;
  return (...a) => {
    const n = Date.now();
    if (n - last >= ms) {
      last = n;
      fn(...a);
    }
  };
}

const memo = fn => {
  const c = new Map();
  return (...a) => {
    const k = JSON.stringify(a);
    if (!c.has(k))
      c.set(k, fn(...a));
    return c.get(k);
  };
};

const curry = fn => function c(...a) {
  return a.length >= fn.length ? fn(...a) : (...b) => c(...a, ...b);
};

const once = fn => {
  let d = false, r;
  return (...a) => d ? r : (d = true, r = fn(...a));
};

Array.prototype.myMap = function (cb) {
  const r = [];
  for (let i = 0; i < this.length; i++)
    r.push(cb(this[i], i, this));
  return r;
};

Array.prototype.myFilter = function (cb) {
  const r = [];
  for (let i = 0; i < this.length; i++)
    if (cb(this[i], i, this))
      r.push(this[i]);
  return r;
};

Array.prototype.myReduce = function (cb, init) {
  let i = 0, acc = init;
  if (acc === undefined)
    acc = this[i++];
  for (; i < this.length; i++)
    acc = cb(acc, this[i], i, this);
  return acc;
};

const pAll = ps => new Promise((res, rej) => {
  const out = [];
  let n = 0;
  ps.forEach((p, i) => Promise.resolve(p).then(v => {
    out[i] = v;
    if (++n === ps.length)
      res(out);
  }, rej));
  if (!ps.length)
    res([]);
});

class Emitter {
  constructor() {
    this.e = {};
  }
  on(n, f) {
    (this.e[n] ||= []).push(f);
  }
  off(n, f) {
    this.e[n] = (this.e[n] || []).filter(x => x !== f);
  }
  emit(n, ...a) {
    (this.e[n] || []).forEach(f => f(...a));
  }
}

async function retry(fn, n = 3) {
  for (let i = 0; i < n; i++) {
    try {
      return await fn();
    }
    catch (e) {
      if (i === n - 1)
        throw e;
    }
  }
}

class Stack {
  #a = [];
  push(x) {
    this.#a.push(x);
  }
  pop() {
    return this.#a.pop();
  }
  peek() {
    return this.#a.at(-1);
  }
  get size() {
    return this.#a.length;
  }
}

class Queue {
  #a = [];
  enqueue(x) {
    this.#a.push(x);
  }
  dequeue() {
    return this.#a.shift();
  }
  get size() {
    return this.#a.length;
  }
}

class Node {
  constructor(v) {
    this.val = v;
    this.next = null;
  }
}
class LL {
  constructor() {
    this.head = null;
  }
  add(v) {
    const n = new Node(v);
    if (!this.head)
      return this.head = n;
    let c = this.head;
    while (c.next)
      c = c.next;
    c.next = n;
  }
}

function reverse(h) {
  let p = null;
  while (h)
    [h.next, p, h] = [p, h, h.next];
  return p;
}

function bfs(g, s) {
  const seen = new Set([s]), q = [s], o = [];
  while (q.length) {
    const n = q.shift();
    o.push(n);
    for (const x of g[n] || [])
      if (!seen.has(x)) {
        seen.add(x);
        q.push(x);
      }
  }
  return o;
}

function dfs(g, n, seen = new Set()) {
  seen.add(n);
  for (const x of g[n] || [])
    if (!seen.has(x))
      dfs(g, x, seen);
  return [...seen];
}

class LRU {
  constructor(c) {
    this.c = c;
    this.m = new Map();
  }
  get(k) {
    if (!this.m.has(k))
      return -1;
    const v = this.m.get(k);
    this.m.delete(k);
    this.m.set(k, v);
    return v;
  }
  put(k, v) {
    this.m.delete(k);
    this.m.set(k, v);
    if (this.m.size > this.c)
      this.m.delete(this.m.keys().next().value);
  }
}

const climb = n => {
  let [a, b] = [1, 1];
  for (let i = 2; i <= n; i++)
    [a, b] = [b, a + b];
  return b;
};

function coins(c, t) {
  const dp = Array(t + 1).fill(Infinity);
  dp[0] = 0;
  for (let i = 1; i <= t; i++)
    for (const x of c)
      if (i >= x)
        dp[i] = Math.min(dp[i], dp[i - x] + 1);
  return dp[t] === Infinity ? -1 : dp[t];
}

function lis(a) {
  const dp = Array(a.length).fill(1);
  for (let i = 1; i < a.length; i++)
    for (let j = 0; j < i; j++)
      if (a[j] < a[i])
        dp[i] = Math.max(dp[i], dp[j] + 1);
  return Math.max(...dp);
}
